import pyomo.environ as pyo
import math

DATA = {
    "villages": [1, 2, 3, 4, 5, 6, 7, 8],
    "x": {1: 10, 2: 10, 3: 12, 4: 14, 5: 16, 6: 18, 7: 8, 8: 6},
    "y": {1: 0, 2: 0, 3: 3, 4: 15, 5: 13, 6: 9, 7: 6, 8: 12},
    "students": {1: 60, 2: 80, 3: 100, 4: 120, 5: 80, 6: 60, 7: 40, 8: 80},
    "num_schools": 2,
}

GOLD_ANSWER = None


def _distance(d, i, j):
    dx = d["x"][i] - d["x"][j]
    dy = d["y"][i] - d["y"][j]
    return math.sqrt(dx * dx + dy * dy)


def build_model(data=None):
    d = data or DATA
    villages = list(d["villages"])
    num_schools = d["num_schools"]

    dist = {(i, j): _distance(d, i, j) for i in villages for j in villages}

    model = pyo.ConcreteModel()
    model.I = pyo.Set(initialize=villages, ordered=True)
    model.IJ = pyo.Set(initialize=[(i, j) for i in villages for j in villages], dimen=2)

    model.open_school = pyo.Var(model.I, within=pyo.Binary)
    model.assign = pyo.Var(model.IJ, within=pyo.Binary)

    def obj_rule(m):
        return sum(
            d["students"][i] * dist[(i, j)] * m.assign[i, j]
            for i in m.I for j in m.I
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def num_schools_rule(m):
        return sum(m.open_school[i] for i in m.I) == num_schools

    model.num_schools_con = pyo.Constraint(rule=num_schools_rule)

    def assign_once_rule(m, i):
        return sum(m.assign[i, j] for j in m.I) == 1

    model.assign_once_con = pyo.Constraint(model.I, rule=assign_once_rule)

    def assign_open_rule(m, i, j):
        return m.assign[i, j] <= m.open_school[j]

    model.assign_open_con = pyo.Constraint(model.IJ, rule=assign_open_rule)

    return model
